16:/// A Protocol Buffers message.
17:pub trait Message: Send + Sync {
18:    /// Encodes the message to a buffer.
19:    ///
20:    /// This method will panic if the buffer has insufficient capacity.
21:    ///
22:    /// Meant to be used only by `Message` implementations.
23:    #[doc(hidden)]
24:    fn encode_raw(&self, buf: &mut impl BufMut)
25:    where
26:        Self: Sized;
27:
28:    /// Polls message-body encoding into an asynchronous encode target.
29:    ///
30:    /// The default implementation delegates to [`Message::encode_raw`]. Derived
31:    /// messages override this method so `string` and `bytes` payload copies can
32:    /// suspend while the rest of the protobuf structure remains CPU-encoded.
33:    #[doc(hidden)]
34:    fn poll_encode_raw<S>(
35:        &self,
36:        target: &mut S,
37:        state: &mut PollEncodeState<S>,
38:        _cx: &mut Context<'_>,
39:    ) -> Poll<Result<(), S::Error>>
40:    where
41:        Self: Sized,
42:        S: AsyncEncodeTarget + Send,
43:    {
44:        if state.field() == 0 {
45:            let mut buf = target.buf_mut();
46:            self.encode_raw(&mut buf);
47:        }
48:        state.clear();
49:        Poll::Ready(Ok(()))
50:    }
51:
52:    /// Encodes the message body to an asynchronous encode target.
53:    ///
54:    /// This future-shaped adapter drives [`Message::poll_encode_raw`] for code
55:    /// that already owns an async encode boundary.
56:    #[doc(hidden)]
57:    fn encode_raw_async<'a, S>(&'a self, target: &'a mut S) -> EncodeRawAsync<'a, Self, S>
58:    where
59:        Self: Sized + 'a,
60:        S: AsyncEncodeTarget + Send + 'a,
61:    {
62:        EncodeRawAsync::new(self, target)
63:    }
64:
65:    /// Decodes a field from a buffer, and merges it into `self`.
66:    ///
67:    /// Meant to be used only by `Message` implementations.
68:    #[doc(hidden)]
69:    fn merge_field(
70:        &mut self,
71:        tag: u32,
72:        wire_type: WireType,
73:        buf: &mut impl Buf,
74:        ctx: DecodeContext,
75:    ) -> Result<(), DecodeError>
76:    where
77:        Self: Sized;
78:
79:    /// Returns the encoded length of the message without a length delimiter.
80:    fn encoded_len(&self) -> usize;
81:
82:    /// Encodes the message to a buffer.
83:    ///
84:    /// An error will be returned if the buffer does not have sufficient capacity.
85:    fn encode(&self, buf: &mut impl BufMut) -> Result<(), EncodeError>
86:    where
87:        Self: Sized,
88:    {
89:        let required = self.encoded_len();
90:        let remaining = buf.remaining_mut();
91:        if required > remaining {
92:            return Err(EncodeError::new(required, remaining));
93:        }
94:
95:        self.encode_raw(buf);
96:        Ok(())
97:    }
98:
99:    /// Encodes the message to a newly allocated buffer.
100:    fn encode_to_vec(&self) -> Vec<u8>
101:    where
102:        Self: Sized,
103:    {
104:        let mut buf = Vec::with_capacity(self.encoded_len());
105:
106:        self.encode_raw(&mut buf);
107:        buf
108:    }
109:
110:    /// Encodes the message with a length-delimiter to a buffer.
111:    ///
112:    /// An error will be returned if the buffer does not have sufficient capacity.
113:    fn encode_length_delimited(&self, buf: &mut impl BufMut) -> Result<(), EncodeError>
114:    where
115:        Self: Sized,
116:    {
117:        let len = self.encoded_len();
118:        let required = len + encoded_len_varint(len as u64);
119:        let remaining = buf.remaining_mut();
120:        if required > remaining {
121:            return Err(EncodeError::new(required, remaining));
122:        }
123:        encode_varint(len as u64, buf);
124:        self.encode_raw(buf);
125:        Ok(())
126:    }
127:
128:    /// Encodes the message with a length-delimiter to a newly allocated buffer.
129:    fn encode_length_delimited_to_vec(&self) -> Vec<u8>
130:    where
131:        Self: Sized,
132:    {
133:        let len = self.encoded_len();
134:        let mut buf = Vec::with_capacity(len + encoded_len_varint(len as u64));
135:
136:        encode_varint(len as u64, &mut buf);
137:        self.encode_raw(&mut buf);
138:        buf
139:    }
140:
141:    /// Decodes an instance of the message from a buffer.
142:    ///
143:    /// The entire buffer will be consumed.
144:    fn decode(mut buf: impl Buf) -> Result<Self, DecodeError>
145:    where
146:        Self: Default,
147:    {
148:        let mut message = Self::default();
149:        Self::merge(&mut message, &mut buf).map(|_| message)
150:    }
151:
152:    /// Decodes a length-delimited instance of the message from the buffer.
153:    fn decode_length_delimited(buf: impl Buf) -> Result<Self, DecodeError>
154:    where
155:        Self: Default,
156:    {
157:        let mut message = Self::default();
158:        message.merge_length_delimited(buf)?;
159:        Ok(message)
160:    }
161:
162:    /// Decodes an instance of the message from a buffer, and merges it into `self`.
163:    ///
164:    /// The entire buffer will be consumed.
165:    fn merge(&mut self, mut buf: impl Buf) -> Result<(), DecodeError>
166:    where
167:        Self: Sized,
168:    {
